        if (data.length < 2) {
            continue; // Skip malformed pairs
        }
        int key;
        try {
            key = Integer.parseInt(data[0], 16);
        } catch (NumberFormatException e) {
            continue;
        }
        String value = data[1];
        if (key == 0x0) {
