private Date readDate(ByteBuf buf, TimeZone timeZone) {
    int year = buf.readUnsignedShort();
    int month = buf.readUnsignedByte();
    int day = buf.readUnsignedByte();
    int hour = buf.readUnsignedByte();
    int minute = buf.readUnsignedByte();
    int second = buf.readUnsignedByte();

    // Adjust year to be in the 2000s if it's a two-digit year
    if (year < 100) {
        year += 2000;
    }

    Calendar calendar = Calendar.getInstance(timeZone);
    calendar.set(Calendar.YEAR, year);
    calendar.set(Calendar.MONTH, month - 1); // Calendar months are 0-based
    calendar.set(Calendar.DAY_OF_MONTH, day);
    calendar.set(Calendar.HOUR_OF_DAY, hour);
    calendar.set(Calendar.MINUTE, minute);
    calendar.set(Calendar.SECOND, second);
    calendar.set(Calendar.MILLISECOND, 0);

    return calendar.getTime();
}

